#include <stdio.h>
#include "settings/settings_manager.h"
#include "host_flash.h"
static void show(const char *tag,const settings_manager_t *m,const host_flash_t *f){ printf("%s seq=%lu slot=%u light=%u telemetry=%u servo=%u dirty=%s saves=%lu recoveries=%lu writes=%lu\n",tag,(unsigned long)m->sequence,m->active_slot,m->settings.light_threshold_lux,m->settings.telemetry_period_ms,m->settings.servo_home_deg,m->dirty?"yes":"no",(unsigned long)m->save_count,(unsigned long)m->recovery_count,(unsigned long)f->write_count); }
int main(void){ host_flash_t flash={0}; settings_storage_t st={&flash,host_flash_read_slot,host_flash_write_slot}; settings_manager_t a; if(!settings_manager_init(&a,&st))return 1; show("boot1",&a,&flash); settings_manager_set_light_threshold(&a,450); settings_manager_set_telemetry_period(&a,2000); settings_manager_set_servo_home(&a,120); if(!settings_manager_save_if_dirty(&a))return 2; show("after_save",&a,&flash); settings_manager_t b; if(!settings_manager_init(&b,&st))return 3; show("boot2_power_restore",&b,&flash); host_flash_corrupt_slot(&flash,b.active_slot); settings_manager_t c; if(!settings_manager_init(&c,&st))return 4; show("boot3_crc_recovery",&c,&flash); return 0; }
